import Mustache from "mustache";

const parentElement = document.querySelector("#GroupBy");
let liCount = parentElement.children.length;

for (const currElem of parentElement.querySelectorAll("li")) {
    const upElem = currElem.querySelector(".up");
    const downElem = currElem.querySelector(".down");
    const removeElem = currElem.querySelector(".remove");

    if (upElem) {
        upElem.addEventListener("click", event => moveUp(event, currElem));
    }

    if (downElem) {
        downElem.addEventListener("click", event => moveDown(event, currElem));
    }

    if (removeElem) {
        removeElem.addEventListener("click", event =>
            removeFromList(event, currElem)
        );
    }
}

function moveUp(event, liElem) {
    const prevElem = liElem.previousElementSibling;
    if (prevElem) {
        parentElement.insertBefore(liElem, prevElem);
        recalculateWeight(parentElement);
    }
}

function moveDown(event, liElem) {
    const nextElem = liElem.nextElementSibling;
    if (nextElem) {
        parentElement.insertBefore(nextElem, liElem);
        recalculateWeight(parentElement);
    }
}

function removeFromList(event, liElem) {
    if (liElem) {
        parentElement.removeChild(liElem);
        liCount--;
        recalculateWeight(parentElement);
    }
}

function recalculateWeight(parentElement) {
    for (let i = 0; i < parentElement.children.length; i++) {
        const weightElem = parentElement.children[i].querySelector(
            "[name='weight']"
        );
        weightElem.value = i;
    }
}

